#' Slope (SLR) - Confidence Interval
#'
#' Bootstrap CI for slope.
#' 
#'
#' @examples
#' data('faithful')
#'
#' slopeCI(dep = eruptions, indep = waiting, data = faithful)
#'
#' @param data the data as a data frame
#' @param dep the dependent variable (not necessary when using a formula, see
#'   the examples)
#' @param indep the independent variable (not necessary when using a formula,
#'   see the examples)
#' @param confLevel a number (default: 95), the confidence level
#' @param ciType .
#' @param coef \code{TRUE} or \code{FALSE} (default), provide model
#'   coefficients
#' @param modelfit \code{TRUE} or \code{FALSE} (default), provide correlation
#'   and R^2
#' @param plots \code{TRUE} or \code{FALSE} (default), provide scatter plot
#'   with regression line.
#' @param reps a number (default: 100), the number of parametric bootstraps
#' @param dotHist .
#' @param showCounts \code{TRUE} or \code{FALSE} (default), whether to print
#'   the count above each bar or dot stack of the simulation plot
#' @param seedBool \code{TRUE} or \code{FALSE} (default), whether to seed the
#'   random number generator
#' @param rngSeed a number (default: 8675309), for seeding the random number
#'   generator
#' @param formula (optional) the formula to use, see the examples
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$coef} \tab \tab \tab \tab \tab a table containing the model coefficients \cr
#'   \code{results$modelfit} \tab \tab \tab \tab \tab a table containing the correlation and R^2 \cr
#'   \code{results$linplot} \tab \tab \tab \tab \tab an array of groups of plots \cr
#'   \code{results$simplot} \tab \tab \tab \tab \tab a plot showing the distribution of slopes \cr
#'   \code{results$CITable} \tab \tab \tab \tab \tab a table containing the CI results \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$coef$asDF}
#'
#' \code{as.data.frame(results$coef)}
#'
#' @export
slopeCI <- function(
    data,
    dep,
    indep,
    confLevel = 95,
    ciType = "bootperc",
    coef = FALSE,
    modelfit = FALSE,
    plots = FALSE,
    reps = 100,
    dotHist = "dotplot",
    showCounts = FALSE,
    seedBool = FALSE,
    rngSeed = 8675309,
    formula) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("slopeCI requires jmvcore to be installed (restart may be required)")

    if ( ! missing(formula)) {
        if (missing(dep))
            dep <- jmvcore::marshalFormula(
                formula=formula,
                data=`if`( ! missing(data), data, NULL),
                from="lhs",
                required=TRUE)
        if (missing(indep))
            indep <- jmvcore::marshalFormula(
                formula=formula,
                data=`if`( ! missing(data), data, NULL),
                from="rhs",
                subset="1")
    }

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(indep)) indep <- jmvcore::resolveQuo(jmvcore::enquo(indep))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(indep), indep, NULL))


    options <- slopeCIOptions$new(
        dep = dep,
        indep = indep,
        confLevel = confLevel,
        ciType = ciType,
        coef = coef,
        modelfit = modelfit,
        plots = plots,
        reps = reps,
        dotHist = dotHist,
        showCounts = showCounts,
        seedBool = seedBool,
        rngSeed = rngSeed)

    analysis <- slopeCIClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

